function validPlan(o){
 if(!o||typeof o!=='object'||!Array.isArray(o.ids))throw Error('This file is not a trip plan.');
 if(o.ids.length>DATA.destinations.length)throw Error('The plan contains too many places.');
 const ids=[...new Set(o.ids)];if(ids.some(id=>typeof id!=='string'||!DEST[id]))throw Error('A destination ID is not recognized.');
 const date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s));
 if(!date(o.startDate)||!date(o.endDate)||o.endDate<o.startDate)throw Error('Choose a valid date window before importing.');
 const visits={};for(const id of ids){const n=Number(o.visits?.[id]??DEST[id].days);if(!Number.isFinite(n)||n<.5||n>30)throw Error('Visit durations must be 0.5–30 days.');visits[id]=n;}
 const modes=(Array.isArray(o.modes)?o.modes:DEFAULT.modes).filter(m=>TRANSPORT_MODES.includes(m));if(!modes.length)throw Error('At least one transport mode must be enabled.');
 return {...DEFAULT,fx:Number.isFinite(Number(o.fx))&&Number(o.fx)>0&&Number(o.fx)<10000?Number(o.fx):DEFAULT.fx,ids,startDate:o.startDate,endDate:o.endDate,month:Number(o.startDate.slice(5,7)),balance:Math.min(100,Math.max(0,Number(o.balance??50)||0)),party:Math.min(20,Math.max(1,Math.round(Number(o.party)||1))),start:ids.includes(o.start)?o.start:'',end:ids.includes(o.end)?o.end:'',loop:!!o.loop,modes,visits,result:null,overrides:{}};
}
function readCookie(name){const key=name+'=';for(const part of document.cookie.split(';')){const s=part.trim();if(s.startsWith(key))try{return decodeURIComponent(s.slice(key.length));}catch(e){return null;}}return null;}
function writeCookie(name,value){const body=encodeURIComponent(value);if(body.length>COOKIE_SAFE)return false;document.cookie=name+'='+body+';path=/;max-age='+(COOKIE_DAYS*86400)+';SameSite=Lax';return true;}
function planPayload(){return JSON.stringify({...state,result:null,overrides:{}});}
function loadSavedPlan(){
 try{const fromCookie=readCookie(STORE);if(fromCookie)return validPlan(JSON.parse(fromCookie));}catch(e){/* Invalid or unavailable cookie; try local fallback. */}
 try{const legacy=localStorage.getItem(STORE);if(legacy){const plan=validPlan(JSON.parse(legacy));try{writeCookie(STORE,JSON.stringify({...plan,result:null,overrides:{}}));}catch(e){}return plan;}}catch(e){/* Storage may be unavailable for file://; JSON export remains usable. */}
 return null;
}
try{const saved=loadSavedPlan();if(saved){state=saved;/* Prior builds auto-pinned the first stop as start; leave order free unless finish or round-trip was set. */if(state.start&&!state.end&&!state.loop)state.start='';/* Drop legacy road/car mode from older saved plans. */state.modes=state.modes.filter(m=>TRANSPORT_MODES.includes(m));if(!state.modes.length)state.modes=[...TRANSPORT_MODES];}}catch(e){}
function persist(){state.modes=state.modes.filter(m=>TRANSPORT_MODES.includes(m));if(!state.modes.length)state.modes=[...TRANSPORT_MODES];const payload=planPayload();try{writeCookie(STORE,payload);}catch(e){/* Cookie may be blocked; export remains available. */}try{localStorage.setItem(STORE,payload);}catch(e){/* Export is always available. */}}
function toast(msg){clearTimeout(toastTimer);$('#toastRoot').innerHTML=`<div class="toast">${esc(msg)}</div>`;toastTimer=setTimeout(()=>$('#toastRoot').innerHTML='',5500);}
