function blocked(d){return !TripEngine.allowed(d,state.month);}
function seasonal(d){
 if(blocked(d)&&d.closureReason)return {status:'closed',label:d.permit==='closed'?'Expedition closed':'Trek unavailable this month',text:d.closureReason};
 if(blocked(d))return {status:'closed',label:d.id==='026'?'Seasonal road unavailable':'Main attraction closed',text:d.id==='026'?'The standard Gurez road approach is excluded from the winter network. Exceptional winter arrangements and foreign-passport eligibility are unresolved; choose a suitable open season before route generation.':'The main high-altitude shrine / flower-valley experience is normally closed in '+MONTHS[state.month-1]+'. Choose an open month or a winter worship destination from the notes.'};
 if(d.climate==='southeast'&&[10,11,12].includes(state.month))return {status:'caution',label:'Northeast monsoon review',text:'The southeast coast can be rainy during October–December. Check current coastal forecasts, cyclone advisories and actual boat or water-activity operations; this is a seasonal note, not a prediction.'};
 if(d.climate==='island'&&[6,7,8,9].includes(state.month))return {status:'caution',label:'Monsoon sea conditions',text:'Island transfers and in-water activities may be limited by rough seas and rain. Confirm the actual operator, approved island and current conditions.'};
 if([11,12,1,2,3].includes(state.month)&&d.decCaution)return {status:'caution',label:'Winter conditions',text:'Snow, ice, short days or reduced services can limit the signature activities. Check the individual destination notes; snow and operation are not guaranteed.'};
 if([6,7,8,9].includes(state.month)&&!['leh','island'].includes(d.climate))return {status:'caution',label:'Monsoon review',text:'Rain, river levels, slippery trails and regional closures can change outdoor activities. Verify the selected cave, trek, river or forest route.'};
 return {status:'good',label:'Seasonal candidate',text:'Generally worth investigating for this month. Activity operations, visibility, weather and entry permissions still need checking.'};
}
function wx(d){const c=DATA.climates[d.climate],i=state.month-1;return {...c,lo:c.low[i],hi:c.high[i],rain:c.rain?.[i],proxy:c.exact&&!(d.id==='071'||d.id==='028'||d.id==='105')};}
