function weatherHtml(d,compact=false){const w=wx(d),season=TripPresentation.weather(d,w,state.month),paths={sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',rain:'<path d="M6 15a4 4 0 1 1 0-8 6 6 0 0 1 11-1 4.5 4.5 0 0 1 1 9M7 18l-1 3m7-3-1 3m7-3-1 3"/>',snow:'<path d="M12 2v20M3 7l18 10M3 17 21 7M9 4l3 3 3-3M9 20l3-3 3 3M3 10l4-1-1-4M21 14l-4 1 1 4M3 14l4 1-1 4M21 10l-4-1 1-4"/>',cold:'<path d="M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0Zm3-8v11"/><circle cx="12" cy="18" r="1"/>',mixed:'<circle cx="8" cy="8" r="4"/><path d="M8 1v2M1 8h2M3 3l2 2m7-2-2 2M7 20a4 4 0 1 1 1-8 5 5 0 0 1 9-1 4.5 4.5 0 0 1 1 9H7"/>'};return `<div class="weather-view ${compact?'compact':''}"><svg class="weather-icon ${season.kind}" viewBox="0 0 24 24" role="img" aria-label="${esc(season.label)}">${paths[season.kind]}</svg><div><strong>${w.exact?'':'~ '}${TripPresentation.fahrenheit(w.lo)}°–${TripPresentation.fahrenheit(w.hi)}°F</strong><small>${Math.round(w.lo)}°–${Math.round(w.hi)}°C${compact?' · '+MONTHS[state.month-1]:''}</small></div></div>${compact?'':`<small class="weather-tendency">${esc(season.label)} · seasonal tendency</small>`}`;}
