function clusterQuery(method,args){return new Promise((resolve,reject)=>{const source=map?.getSource('destinations');if(!source||typeof source[method]!=='function'){reject(Error('Cluster source unavailable'));return;}let settled=false;const done=(err,value)=>{if(settled)return;settled=true;err?reject(err):resolve(value);};try{const pending=source[method](...args,done);if(pending?.then)pending.then(v=>done(null,v),done);}catch(e){done(e);}});}
